subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "deal_name": {
      "maxLength": 128,
      "pattern": "^[A-Za-z0-9 ._-]+$",
      "type": "string"
    },
    "debt_tranches": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "amount": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "name": {
            "maxLength": 64,
            "pattern": "^[A-Za-z0-9 ._-]+$",
            "type": "string"
          },
          "rate": {
            "maxLength": 16,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "type": {
            "enum": [
              "senior_secured",
              "senior_unsecured",
              "mezzanine",
              "equity",
              "pik",
              "revolver",
              "other"
            ]
          }
        },
        "type": "object"
      },
      "maxItems": 10,
      "type": "array"
    },
    "entry_ev": {
      "maxLength": 32,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "exit_ev": {
      "maxLength": 32,
      "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
      "type": "string"
    },
    "lbo_outputs": {
      "additionalProperties": false,
      "properties": {
        "irr_base": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "irr_bear": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "irr_bull": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "moic_base": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "moic_bear": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "moic_bull": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        }
      },
      "type": "object"
    },
    "sources_uses": {
      "description": "Sources and uses table with totals",
      "type": "object"
    }
  },
  "required": [
    "deal_name",
    "entry_ev",
    "lbo_outputs"
  ],
  "type": "object"
}
